/* Grid Keeper: level content. Every challenge is grounded in the circuit-theory lecture guide. */
const { rnd, pick, fmt, shuffle } = Kit;
const R2 = Math.SQRT2, R3 = Math.sqrt(3), D2R = Math.PI / 180;
const sgn = n => (n < 0 ? '−' : '+') + Math.abs(n);

const OLD = [
  /* ---------------------------------------------------------------- 1 */
  { n: 1, diff: 1, topic: 'Power on the Wire', theme: { parts: ['R', 'L', 'C'], phase: 0 },
    blurb: 'Instantaneous vs average power, rms, and how resistors, coils and capacitors treat power.',
    intro: 'Power is voltage times current at every instant. In AC both wiggle, so power wiggles too. The <b>average</b> of that wiggle is the real work (heat, light, motion). A resistor uses all of it. A coil or capacitor only borrows energy and gives it back.',
    chals: [
      { t: 'choice', tier: 1, q: 'An AC source feeds a plain resistor. What happens to the power it absorbs?', opts: ['All of it becomes heat, and p(t) never goes negative', 'Half of it is handed back to the source each cycle', 'The average power is zero', 'The current leads the voltage by 90°'], a: 0, hint: 'A resistor keeps everything it receives.', why: 'A resistor turns all its power into heat. Its p(t) bumps between 0 and 2P and never goes below zero.' },
      { t: 'match', tier: 1, q: 'Match each part to how its current behaves compared to its voltage.', pairs: [['Resistor', 'In phase'], ['Inductor (coil)', 'Current lags voltage by 90°'], ['Capacitor', 'Current leads voltage by 90°']], extra: ['Current is always zero'], why: 'Resistor: in phase. Inductor: current lags (v = L di/dt). Capacitor: current leads (i = C dv/dt).' },
      { t: 'num', tier: 1, gen() { const Vm = pick([100, 141, 170, 200, 311]); return { q: 'A sinusoidal voltage has a peak of <span class="m">' + Vm + ' V</span>. What is its rms value?', given: ['V<sub>m</sub> = ' + Vm + ' V'], unit: 'V', a: Vm / R2, tol: 0.02, hint: 'V<sub>rms</sub> = V<sub>m</sub> / √2.', why: 'V<sub>rms</sub> = V<sub>m</sub>/√2 = ' + fmt(Vm / R2, 1) + ' V. A 170 V peak wall outlet is the familiar 120 V rms.' }; } },
      { t: 'choice', tier: 2, q: 'The voltage runs at frequency ω. How fast does the power wave p(t) = v(t)·i(t) wiggle?', opts: ['At 2ω, twice as fast', 'At ω, the same speed', 'At ω/2, half as fast', 'It does not wiggle at all'], a: 0, hint: 'A product of two waves at ω has a term at 2ω.', why: 'Multiplying two waves at ω creates a term at 2ω. That is why instantaneous power wiggles at twice the line frequency.' },
      { t: 'sort', tier: 2, q: 'Sort each example into real power or reactive power.', buckets: ['Real power P (does work)', 'Reactive power Q (sloshes)'], items: [['Heat in a toaster element', 0], ['Energy stored in a coil, then returned', 1], ['Light from a bulb', 0], ['A capacitor charging, then discharging', 1], ['Motion at a motor shaft', 0]], why: 'Real power is used up (heat, light, motion). Reactive power is energy that flows in and out of fields and is never used up.' },
      { t: 'num', tier: 3, boss: true, gen() { const Vm = pick([100, 150, 170, 200]), R = pick([10, 20, 25, 50]); return { q: 'A voltage <span class="m">v(t) = ' + Vm + ' cos(ωt)</span> V is applied across a resistor. Find the average power it absorbs.', given: ['V<sub>m</sub> = ' + Vm + ' V', 'R = ' + R + ' Ω'], unit: 'W', a: Vm * Vm / (2 * R), tol: 0.02, hint: 'Find V<sub>rms</sub> first, then P = V<sub>rms</sub>² / R.', why: 'V<sub>rms</sub> = ' + fmt(Vm / R2, 2) + ' V, so P = V<sub>rms</sub>²/R = ' + fmt(Vm * Vm / (2 * R), 1) + ' W. Same as V<sub>m</sub>²/(2R).' }; } },
    ] },

  /* ---------------------------------------------------------------- 2 */
  { n: 2, diff: 1, topic: 'Power Factor and the Phase Angle', theme: { parts: ['L', 'R'], phase: 40 },
    blurb: 'ELI the ICE man, lagging and leading loads, and finding real power from the angle.',
    intro: 'The angle between voltage and current decides how much power is <b>real</b>. The power factor is <span class="m">pf = cos(θ<sub>v</sub> − θ<sub>i</sub>)</span>. A resistive load has pf 1. Motors and fans lag. Capacitive loads lead.',
    chals: [
      { t: 'choice', tier: 1, q: 'Remember “ELI the ICE man”. In an <b>inductor</b>, which one comes first?', opts: ['Voltage (E) comes first, so current lags', 'Current (I) comes first, so current leads', 'They are always exactly together', 'Neither: an inductor has no phase shift'], a: 0, hint: 'E, L, I: voltage, inductor, current, in that order.', why: 'ELI: voltage (E) before current (I) in an inductor (L), so the current lags. ICE: in a capacitor (C), current leads.' },
      { t: 'sort', tier: 1, q: 'Sort each load by its power factor type.', buckets: ['Lagging', 'Leading', 'Unity (pf = 1)'], items: [['Electric motor', 0], ['Resistive heater', 2], ['Computer with a switched-mode supply', 1], ['Refrigerator', 0], ['Ceiling fan', 0], ['Capacitive load', 1]], why: 'Motors, fans and fridges are inductive, so they lag. Resistive loads are unity. A switched-mode computer supply can lead.' },
      { t: 'num', tier: 2, gen() { const tv = pick([0, 15, 30, -20]), d = pick([30, 45, 60, -30, -45]); const ti = tv - d; return { q: 'A load has voltage angle <span class="m">θ<sub>v</sub> = ' + tv + '°</span> and current angle <span class="m">θ<sub>i</sub> = ' + ti + '°</span>. What is the power factor?', given: ['θ<sub>v</sub> = ' + tv + '°', 'θ<sub>i</sub> = ' + ti + '°'], a: Math.cos(d * D2R), tol: 0.02, abs: 0.006, hint: 'pf = cos(θ<sub>v</sub> − θ<sub>i</sub>).', why: 'θ<sub>v</sub> − θ<sub>i</sub> = ' + d + '°, so pf = cos(' + d + '°) = ' + fmt(Math.cos(d * D2R), 3) + '.' }; } },
      { t: 'choice', tier: 2, q: 'A load has pf = 0.5. Does that tell you the load is lagging?', opts: ['No. cos 60° and cos(−60°) are both 0.5, so you must also say lagging or leading', 'Yes. A pf below 1 always means lagging', 'Yes. A pf of 0.5 always means a motor', 'No. A pf of 0.5 is impossible'], a: 0, hint: 'Cosine is an even function.', why: 'The angle trap: pf alone does not give the angle. You need “lagging” or “leading”, or the sign of Q.' },
      { t: 'choice', tier: 2, q: 'A current is written <span class="m">i = 4 sin(ωt + 135°)</span> A. Written as a cosine, what is its phase angle?', opts: ['45°', '135°', '225°', '−45°'], a: 0, hint: 'sin(x + 135°) = cos(x + 135° − 90°).', why: 'sin(x) = cos(x − 90°), so sin(ωt + 135°) = cos(ωt + 45°). The angle is 45°.' },
      { t: 'num', tier: 3, boss: true, gen() { const Vm = pick([100, 120, 200]), Im = pick([2, 4, 5]), d = pick([30, 45, 60, -30, -60]); const tv = pick([10, 15, 20]); return { q: 'A load sees <span class="m">v = ' + Vm + ' cos(ωt + ' + tv + '°)</span> V and <span class="m">i = ' + Im + ' cos(ωt ' + sgn(tv - d).replace('+', '+ ').replace('−', '− ') + '°)</span> A. Find the average (real) power.', unit: 'W', a: 0.5 * Vm * Im * Math.cos(d * D2R), tol: 0.02, hint: 'P = ½ V<sub>m</sub> I<sub>m</sub> cos(θ<sub>v</sub> − θ<sub>i</sub>). Find the angle difference first.', why: 'θ<sub>v</sub> − θ<sub>i</sub> = ' + d + '°. P = ½(' + Vm + ')(' + Im + ')cos(' + d + '°) = ' + fmt(0.5 * Vm * Im * Math.cos(d * D2R), 1) + ' W.' }; } },
    ] },

  /* ---------------------------------------------------------------- 3 */
  { n: 3, diff: 2, topic: 'Complex Power and the Power Triangle', theme: { parts: ['L', 'R'], phase: 55 },
    blurb: 'Pack P and Q into S = P + jQ, then use apparent power to size wires.',
    intro: 'Bundle real power <b>P</b> and reactive power <b>Q</b> into one complex number, <span class="m">S = P + jQ</span>. Its size is the <b>apparent power</b> (what the wires must carry). Its angle is the power factor angle.',
    chals: [
      { t: 'match', tier: 1, q: 'Match each symbol to what it means.', pairs: [['P', 'Average (real) power, in W'], ['Q', 'Reactive power, in VAR'], ['S', 'Complex power, S = P + jQ'], ['|S|', 'Apparent power, in VA']], why: 'P in watts, Q in vars, S and |S| in volt-amps. |S| = √(P² + Q²).' },
      { t: 'choice', tier: 1, q: 'What does the <b>angle</b> of the complex power S equal?', opts: ['θ<sub>v</sub> − θ<sub>i</sub>, the power factor angle', 'θ<sub>v</sub> + θ<sub>i</sub>', 'Always 0°', 'The phase of the source only'], a: 0, hint: 'S = V<sub>rms</sub> I<sub>rms</sub> ∠(θ<sub>v</sub> − θ<sub>i</sub>).', why: 'S = V<sub>rms</sub>I<sub>rms</sub>∠(θ<sub>v</sub> − θ<sub>i</sub>), so its angle is the power factor angle.' },
      { t: 'num', tier: 2, gen() { const t = pick([[3, 4, 5], [5, 12, 13], [8, 15, 17], [20, 21, 29]]), k = pick([10, 20, 100]); return { q: 'A load absorbs <span class="m">P = ' + t[0] * k + ' W</span> and <span class="m">Q = ' + t[1] * k + ' VAR</span>. Find the apparent power |S|.', given: ['P = ' + t[0] * k + ' W', 'Q = ' + t[1] * k + ' VAR'], unit: 'VA', a: t[2] * k, tol: 0.01, hint: 'Power triangle: |S| = √(P² + Q²).', why: '|S| = √(' + t[0] * k + '² + ' + t[1] * k + '²) = ' + t[2] * k + ' VA.' }; } },
      { t: 'num', tier: 2, gen() { const S = pick([10, 20, 50]), pf = pick([0.6, 0.8, 0.85, 0.9]); return { q: 'A load has <span class="m">|S| = ' + S + ' kVA</span> at a lagging <span class="m">pf = ' + pf + '</span>. Find the real power P.', given: ['|S| = ' + S + ' kVA', 'pf = ' + pf], unit: 'kW', a: S * pf, tol: 0.01, hint: 'Real power = apparent power × power factor.', why: 'P = |S| × pf = ' + S + ' × ' + pf + ' = ' + fmt(S * pf, 2) + ' kW.' }; } },
      { t: 'choice', tier: 2, q: 'Two loads share one source. What adds up to give the total?', opts: ['The complex power S of each piece', 'The apparent powers |S|, always', 'The squares of the voltages', 'Nothing adds. Power never combines'], a: 0, hint: 'Squaring is not linear, but complex power of each element is additive.', why: 'Total S = sum of the S of every piece. You cannot add the |S| values unless the angles match. Power itself does not superpose for sources.' },
      { t: 'num', tier: 3, boss: true, gen() { const S = pick([10, 20, 30]), V = pick([100, 125, 240]), R = pick([0.01, 0.02, 0.05]); const I = S * 1000 / V; return { q: 'A load draws <span class="m">|S| = ' + S + ' kVA</span> at <span class="m">' + V + ' V</span> rms. The line feeding it has resistance <span class="m">' + R + ' Ω</span>. How much power does the line itself waste?', given: ['|S| = ' + S + ' kVA', 'V = ' + V + ' V rms', 'R<sub>line</sub> = ' + R + ' Ω'], unit: 'W', a: I * I * R, tol: 0.02, hint: 'Find |I| = |S| / V<sub>rms</sub> first. Line loss is I²R.', why: '|I| = ' + S * 1000 + '/' + V + ' = ' + fmt(I, 1) + ' A. Loss = I²R = ' + fmt(I * I * R, 1) + ' W.' }; } },
    ] },

  /* ---------------------------------------------------------------- 4 */
  { n: 4, diff: 2, topic: 'Fix the Line: Power Factor Correction and Max Power', theme: { parts: ['L', 'C'], phase: 30 },
    blurb: 'Cut line loss with a parallel capacitor, use admittance, and match a load for maximum power.',
    intro: 'A motor-type load draws extra current just to slosh reactive energy. A capacitor <b>in parallel</b> supplies that sloshing locally, so the line carries less current and wastes less. Line loss is <span class="m">I²R</span>.',
    chals: [
      { t: 'choice', tier: 1, q: 'Why add a capacitor next to a motor-type load?', opts: ['It supplies the reactive power locally, so the line current drops', 'It makes the motor spin faster', 'It adds real power to the load', 'It raises the line voltage'], a: 0, hint: 'Less current in the line means less I²R loss.', why: 'The capacitor handles the sloshing energy near the load. The source then sees a pf near 1, with less current and less wasted heat.' },
      { t: 'sort', tier: 1, q: 'Parallel or series capacitor? Sort each effect.', buckets: ['Capacitor in parallel', 'Capacitor in series'], items: [['Load voltage stays the same', 0], ['Line current drops', 0], ['Line loss is not reduced', 1], ['Load current is changed', 1], ['The correct fix', 0]], why: 'In parallel, the load voltage and current are unchanged but the line current drops. In series, the load current is unchanged, so the loss is not reduced.' },
      { t: 'num', tier: 2, gen() { const I1 = pick([10, 12, 20]), I2 = pick([5, 6, 8]), R = pick([0.5, 1, 2]); return { q: 'Power factor correction cuts the line current from <span class="m">' + I1 + ' A</span> to <span class="m">' + I2 + ' A</span>. The line resistance is <span class="m">' + R + ' Ω</span>. How many watts of line loss are saved?', given: ['I before = ' + I1 + ' A', 'I after = ' + I2 + ' A', 'R = ' + R + ' Ω'], unit: 'W', a: (I1 * I1 - I2 * I2) * R, tol: 0.02, hint: 'Loss = I²R before, minus loss after.', why: 'Before: ' + fmt(I1 * I1 * R, 1) + ' W. After: ' + fmt(I2 * I2 * R, 1) + ' W. Saved: ' + fmt((I1 * I1 - I2 * I2) * R, 1) + ' W.' }; } },
      { t: 'num', tier: 2, gen() { const z = pick([[3, 4], [6, 8], [4, 3], [8, 6]]), w = pick([100, 200]); const B = z[1] / (z[0] * z[0] + z[1] * z[1]); return { q: 'A load has <span class="m">Z<sub>L</sub> = ' + z[0] + ' + j' + z[1] + ' Ω</span> at <span class="m">ω = ' + w + ' rad/s</span>. Find the parallel capacitance that cancels its susceptance.', given: ['Z = ' + z[0] + ' + j' + z[1] + ' Ω', 'ω = ' + w + ' rad/s'], unit: 'mF', a: 1000 * B / w, tol: 0.02, hint: 'Y = 1/Z = G + jB. Pick ωC to cancel the load’s susceptance.', why: 'Y = 1/Z = ' + fmt(z[0] / (z[0] ** 2 + z[1] ** 2), 3) + ' − j' + fmt(B, 3) + ' S. Set ωC = ' + fmt(B, 3) + ', so C = ' + fmt(1000 * B / w, 2) + ' mF.' }; } },
      { t: 'choice', tier: 2, q: 'You can choose both R<sub>L</sub> and X<sub>L</sub>. For <b>maximum power</b> into the load, pick Z<sub>L</sub> equal to…', opts: ['The complex conjugate of the source impedance, Z<sub>s</sub>*', 'The source impedance Z<sub>s</sub> itself', 'Zero', 'As large as possible'], a: 0, hint: 'You want the reactances to cancel.', why: 'Z<sub>L</sub> = Z<sub>s</sub>* means the same resistance and opposite reactance. The reactances cancel and R<sub>L</sub> matches R<sub>s</sub>.' },
      { t: 'num', tier: 3, boss: true, gen() { const Vs = pick([10, 20, 50, 120]), Rs = pick([1, 2, 5, 10]); return { q: 'A source with rms voltage <span class="m">' + Vs + ' V</span> and impedance <span class="m">' + Rs + ' + jX<sub>s</sub> Ω</span> drives a load chosen for maximum power transfer. How much real power reaches the load?', given: ['V<sub>s</sub> = ' + Vs + ' V rms', 'R<sub>s</sub> = ' + Rs + ' Ω'], unit: 'W', a: Vs * Vs / (4 * Rs), tol: 0.02, hint: 'P<sub>L</sub> = V<sub>s</sub>²R<sub>L</sub> / [(R<sub>L</sub>+R<sub>s</sub>)² + (X<sub>L</sub>+X<sub>s</sub>)²]. Set X<sub>L</sub> = −X<sub>s</sub> and R<sub>L</sub> = R<sub>s</sub>.', why: 'With X<sub>L</sub> = −X<sub>s</sub> and R<sub>L</sub> = R<sub>s</sub>, P<sub>L</sub> = V<sub>s</sub>²R<sub>s</sub>/(2R<sub>s</sub>)² = V<sub>s</sub>²/(4R<sub>s</sub>) = ' + fmt(Vs * Vs / (4 * Rs), 1) + ' W.' }; } },
    ] },

  /* ---------------------------------------------------------------- 5 */
  { n: 5, diff: 2, topic: 'Three-Phase Basics', theme: { parts: ['R', 'R', 'R'], phase: 120 },
    blurb: 'Balanced sets, abc and acb sequence, why the grid uses three phases, and the path from generator to outlet.',
    intro: 'Three-phase power is three AC waves offset by 120°. A balanced set adds to zero at every instant, which is why it needs so few wires.',
    chals: [
      { t: 'choice', tier: 1, q: 'In a balanced <b>abc</b> (positive) set, V<sub>a</sub> = V<sub>m</sub>∠0°. What is V<sub>b</sub>?', opts: ['V<sub>m</sub>∠−120°', 'V<sub>m</sub>∠+120°', 'V<sub>m</sub>∠−90°', 'V<sub>m</sub>∠180°'], a: 0, hint: 'abc: b = a − 120°, c = a + 120°.', why: 'abc sequence: b-phase is a − 120°, c-phase is a + 120°. In acb you do the opposite.' },
      { t: 'match', tier: 1, q: 'Match each phase to its angle (V<sub>a</sub> = V<sub>m</sub>∠0° in both sequences).', pairs: [['abc: b-phase', '−120°'], ['abc: c-phase', '+120°'], ['acb: b-phase', '+120°'], ['acb: c-phase', '−120°']], why: 'abc: b = −120°, c = +120°. acb flips them. In both, V<sub>a</sub> + V<sub>b</sub> + V<sub>c</sub> = 0.' },
      { t: 'sort', tier: 2, q: 'Is each set a <b>balanced</b> three-phase set?', buckets: ['Balanced', 'Not balanced'], items: [['120∠0°, 120∠−120°, 120∠+120° V', 0], ['120∠0°, 120∠−90°, 120∠+90° V', 1], ['100∠0°, 100∠120°, 100∠240° V', 0], ['100∠0°, 80∠−120°, 100∠+120° V', 1], ['120∠0°, 120∠0°, 120∠0° V', 1]], why: 'Balanced means equal sizes, 120° apart, adding to zero. Note 240° is the same as −120°.' },
      { t: 'choice', tier: 2, q: 'Why does the grid use three phases?', opts: ['Three wires carry three times the power of two wires (single phase), with no extra return wire', 'Three phases make the voltage three times higher', 'Single phase cannot be transformed', 'Three phases remove the need for any ground'], a: 0, hint: 'Count wires per unit of power.', why: 'The three waves cancel at the neutral point, so no extra return is needed. Three wires carry 3 times the power of two wires.' },
      { t: 'order', tier: 2, q: 'Put the path from generator to home in order.', items: ['Generator (wye), 13.8 kV', 'Step-up transformer to 138 kV for long-distance transmission', 'Substation steps down to 13.8 kV', 'Neighborhood transformer steps down to 120/240 V', 'Home: 120 V and 240 V outlets'], hint: 'Voltage goes up for transmission, then down toward the home.', why: 'High voltage for the long haul means less current and less loss. Transformers then step it down in stages to 120/240 V.' },
      { t: 'num', tier: 3, boss: true, gen() { const mode = pick(['line', 'phase']); if (mode === 'line') { const Vp = pick([120, 277, 7970]); return { q: 'A balanced Y source has a phase voltage of <span class="m">' + Vp + ' V</span>. What is the line-to-line voltage?', unit: 'V', a: Vp * R3, tol: 0.01, hint: 'Line voltage is √3 times phase voltage.', why: 'V<sub>line</sub> = √3 × ' + Vp + ' = ' + fmt(Vp * R3, 1) + ' V. (120 V phase gives about 208 V line.)' }; } const VL = pick([13.8, 138, 4.16]); return { q: 'The line-to-line voltage is <span class="m">' + VL + ' kV</span> on a wye system. What is the voltage across one phase?', unit: 'kV', a: VL / R3, tol: 0.01, hint: 'Phase voltage is line voltage divided by √3.', why: 'V<sub>phase</sub> = ' + VL + '/√3 = ' + fmt(VL / R3, 2) + ' kV. (13.8 kV line gives about 7.97 kV phase.)' }; } },
    ] },

  /* ---------------------------------------------------------------- 6 */
  { n: 6, diff: 3, topic: 'Balanced Y and Delta Circuits', theme: { parts: ['L', 'R', 'R'], phase: 30 },
    blurb: 'Line vs phase quantities, the 30° rule, the Δ-Y trick, and the one-phase shortcut.',
    intro: 'If all three phases are identical, the neutral wire carries zero current. Solve <b>one phase</b>, then shift the answers by ±120°. To handle a Δ load, swap it for a Y with one third the impedance.',
    chals: [
      { t: 'sort', tier: 1, q: 'Sort each fact by the connection it describes.', buckets: ['Y (wye)', 'Δ (delta)'], items: [['Phase current equals line current', 0], ['Phase voltage equals line voltage', 1], ['Has a center point (neutral)', 0], ['Three branches joined in a triangle', 1], ['Phase current is line current ÷ √3', 1]], why: 'Rule of thumb: in a Y, phase current = line current. In a Δ, phase voltage = line voltage.' },
      { t: 'choice', tier: 1, q: 'In a balanced Y-Y circuit, what is the neutral wire’s current?', opts: ['Zero, so you can solve just one phase', 'Three times one phase current', 'Equal to the line current', 'It depends on the load order'], a: 0, hint: 'The three equal currents are 120° apart.', why: 'Balanced currents add to zero at the neutral. That is why the one-phase shortcut works.' },
      { t: 'num', tier: 2, gen() { const Z = pick([30, 60, 90, 120, 150]); return { q: 'A balanced Δ load has <span class="m">' + Z + ' Ω</span> in each leg. What is the impedance of each leg of the equivalent Y?', unit: 'Ω', a: Z / 3, tol: 0.01, hint: 'For a balanced load, Z<sub>Y</sub> = Z<sub>Δ</sub> / 3.', why: 'Balanced shortcut: Z<sub>Y</sub> = Z<sub>Δ</sub>/3 = ' + fmt(Z / 3, 2) + ' Ω.' }; } },
      { t: 'choice', tier: 2, q: 'For an <b>abc</b> sequence, how does the line voltage V<sub>AB</sub> compare to the phase voltage V<sub>AN</sub>?', opts: ['√3 times as large, leading by 30°', '√3 times as large, lagging by 30°', 'The same size, leading by 120°', '1/√3 as large, leading by 30°'], a: 0, hint: 'V<sub>AB</sub> = V<sub>AN</sub> − V<sub>BN</sub>.', why: 'For abc, V<sub>AB</sub> = √3∠+30° · V<sub>AN</sub>. For acb it is √3∠−30°.' },
      { t: 'num', tier: 2, gen() { const VL = pick([208, 400, 416, 480]); return { q: 'A balanced Y system has a line-to-line voltage of <span class="m">' + VL + ' V</span>. What is each phase voltage (magnitude)?', unit: 'V', a: VL / R3, tol: 0.01, hint: 'Phase = line ÷ √3.', why: '|V<sub>phase</sub>| = ' + VL + '/√3 = ' + fmt(VL / R3, 1) + ' V.' }; } },
      { t: 'num', tier: 3, boss: true, gen() { const V = pick([120, 240]), T = pick([[40, 30], [30, 40], [80, 60], [60, 80]]); return { q: 'A balanced Y-Y circuit has a-phase source <span class="m">' + V + '∠0° V</span>. Per phase: <span class="m">Z<sub>g</sub> = 0.5 + j1</span>, <span class="m">Z<sub>l</sub> = 1.5 + j2</span>, <span class="m">Z<sub>L</sub> = ' + (T[0] - 2) + ' + j' + (T[1] - 3) + '</span> Ω. Find the size of the line current |I<sub>aA</sub>|.', given: ['V = ' + V + ' V', 'Z total = Z<sub>g</sub> + Z<sub>l</sub> + Z<sub>L</sub>'], unit: 'A', a: V / Math.hypot(T[0], T[1]), tol: 0.02, hint: 'Add the three impedances, then |I| = |V| / |Z|.', why: 'Z<sub>φ</sub> = ' + T[0] + ' + j' + T[1] + ' Ω, |Z<sub>φ</sub>| = ' + Math.hypot(T[0], T[1]) + ' Ω. |I| = ' + V + '/' + Math.hypot(T[0], T[1]) + ' = ' + fmt(V / Math.hypot(T[0], T[1]), 2) + ' A.' }; } },
    ] },

  /* ---------------------------------------------------------------- 7 */
  { n: 7, diff: 3, topic: 'Three-Phase Power and Electrical Safety', theme: { parts: ['R', 'R', 'R'], phase: 0 },
    blurb: 'Total three-phase power, why it never wiggles, grounding, GFCIs and what current does to the body.',
    intro: 'Total real power is <span class="m">P = √3 · V<sub>line</sub> · I<sub>line</sub> · cos θ</span>, and the three phases fill in each other’s dips so the total never wiggles. Safety half: <b>current</b>, not voltage, hurts you.',
    chals: [
      { t: 'choice', tier: 1, q: 'What does the <b>total</b> instantaneous power of a balanced three-phase load look like over time?', opts: ['Constant. The 2ω wiggles cancel', 'A wave at 2ω', 'A wave at 3ω', 'Zero at all times'], a: 0, hint: 'Think of three people pedaling a bike, each a third of a turn apart.', why: 'Each phase has a 2ω wiggle. Add all three and the wiggles cancel, leaving a constant. That gives smooth motor torque.' },
      { t: 'sort', tier: 1, q: 'Sort each current by its effect on the body (60 Hz).', buckets: ['Tingle', 'Cannot let go or breathe', 'Heart fibrillation', 'Burns'], items: [['0.5 to 3 mA', 0], ['6 to 22 mA', 1], ['75 to 400 mA', 2], ['5 to 10 A', 3], ['18 to 22 mA (breathing muscles lock)', 1]], why: 'A few mA tingles, above the let-go current you cannot release, 75 to 400 mA can fibrillate the heart, and several amps burn.' },
      { t: 'num', tier: 2, gen() { const V = pick([208, 400, 480]), I = pick([10, 20, 50]), pf = pick([0.8, 0.85, 0.9]); return { q: 'A balanced three-phase load has line voltage <span class="m">' + V + ' V</span>, line current <span class="m">' + I + ' A</span> and a power factor of <span class="m">' + pf + '</span>. Find the total real power.', unit: 'kW', a: R3 * V * I * pf / 1000, tol: 0.02, hint: 'P = √3 · V<sub>line</sub> · I<sub>line</sub> · pf.', why: 'P = √3 × ' + V + ' × ' + I + ' × ' + pf + ' = ' + fmt(R3 * V * I * pf / 1000, 2) + ' kW. The same formula works for Y and Δ.' }; } },
      { t: 'choice', tier: 2, q: 'What does a GFCI outlet measure?', opts: ['The difference between current going out and current returning (trips near 4 to 6 mA)', 'The total current (trips near 15 to 20 A)', 'The line voltage', 'The power factor'], a: 0, hint: 'A leak to ground makes the two currents differ.', why: 'A GFCI protects people by sensing leakage. A circuit breaker protects wires by sensing total current.' },
      { t: 'choice', tier: 2, q: 'You hold the hot wire in one hand and the neutral in the other, standing on a dry wood floor. Will a GFCI trip?', opts: ['No. Current goes in one hand and out the other, so out equals back', 'Yes, instantly', 'Yes, but only above 20 A', 'Only if the plug is polarized'], a: 0, hint: 'What does the GFCI compare?', why: 'The GFCI’s blind spot: the current returns through the neutral, so it sees no leak. Never rely on a GFCI alone.' },
      { t: 'num', tier: 3, boss: true, gen() { const V = pick([208, 400, 480]), I = pick([20, 25, 40]), pf = pick([0.6, 0.8]); const Q = R3 * V * I * Math.sqrt(1 - pf * pf) / 1000; return { q: 'A balanced load has line voltage <span class="m">' + V + ' V</span>, line current <span class="m">' + I + ' A</span> and <span class="m">pf = ' + pf + '</span> lagging. Find the total reactive power Q.', unit: 'kVAR', a: Q, tol: 0.02, hint: 'Q = √3 V<sub>line</sub> I<sub>line</sub> sin θ, and sin θ = √(1 − pf²).', why: 'sin θ = ' + fmt(Math.sqrt(1 - pf * pf), 2) + '. Q = √3 × ' + V + ' × ' + I + ' × ' + fmt(Math.sqrt(1 - pf * pf), 2) + ' = ' + fmt(Q, 2) + ' kVAR.' }; } },
    ] },

  /* ---------------------------------------------------------------- 8 */
  { n: 8, diff: 3, topic: 'Laplace Basics: Step, Impulse, Transform Pairs', theme: { parts: ['C', 'R'], phase: -60 },
    blurb: 'The unit step, the unit impulse, the sifting property and the first transform pairs.',
    intro: 'The Laplace transform swaps a hard calculus problem for easy algebra in a complex variable <b>s</b>. You transform, do algebra, then transform back. The <b>step</b> is a switch flipping on. The <b>impulse</b> is an instant spike with area 1.',
    chals: [
      { t: 'match', tier: 1, q: 'Match each time signal to its Laplace transform.', pairs: [['Unit step u(t)', '1/s'], ['Unit impulse δ(t)', '1'], ['e<sup>−at</sup> u(t)', '1/(s + a)'], ['t · u(t)', '1/s²']], extra: ['s'], why: 'Standard pairs: u(t) ↔ 1/s, δ(t) ↔ 1, e<sup>−at</sup>u(t) ↔ 1/(s+a), t·u(t) ↔ 1/s².' },
      { t: 'choice', tier: 1, q: 'Which description fits the <b>unit impulse</b> δ(t)?', opts: ['Zero everywhere except t = 0, with total area 1', 'Equal to 1 for all t > 0', 'A sine wave of unit amplitude', 'A ramp with slope 1'], a: 0, hint: 'It is the limit of a pulse with width ε and height 1/ε.', why: 'δ(t) has area 1 packed into an instant. The step u(t) is the one that equals 1 for t > 0.' },
      { t: 'num', tier: 2, gen() { const a = rnd(1, 5), k = rnd(1, 6); const inside = Math.random() < 0.75; if (inside) return { q: 'Evaluate <span class="m">∫ (t² + ' + k + ') δ(t − ' + a + ') dt</span> over all t.', a: a * a + k, tol: 0.001, abs: 0.001, hint: 'The impulse sifts out the value of the function at t = ' + a + '.', why: 'Sifting property: the integral equals f(' + a + ') = ' + a + '² + ' + k + ' = ' + (a * a + k) + '.' }; return { q: 'Evaluate <span class="m">∫<sub>0</sub><sup>' + (a - 1 > 0 ? a - 1 : 0.5) + '</sup> (t² + ' + k + ') δ(t − ' + a + ') dt</span>.', a: 0, tol: 0.001, abs: 0.001, hint: 'Is the spike inside the limits?', why: 'The spike at t = ' + a + ' lies outside the limits of integration, so the integral is 0.' }; } },
      { t: 'choice', tier: 2, q: 'Why use the Laplace transform for circuits?', opts: ['It turns differential equations into algebra and builds in initial conditions', 'It makes every circuit linear', 'It removes the need for sources', 'It only works for DC circuits'], a: 0, hint: 'Transform, solve, transform back.', why: 'It gives the complete response, transient plus steady state, in one go, with the starting conditions built in (values at 0⁻).' },
      { t: 'num', tier: 2, gen() { if (Math.random() < 0.5) { const a = rnd(1, 4), s = rnd(1, 5); return { q: 'The transform of <span class="m">e<sup>−' + a + 't</sup> u(t)</span> is F(s). Evaluate F(s) at <span class="m">s = ' + s + '</span>.', a: 1 / (s + a), tol: 0.02, hint: 'F(s) = 1/(s + a).', why: 'F(s) = 1/(s + ' + a + ') = 1/' + (s + a) + ' = ' + fmt(1 / (s + a), 4) + '.' }; } const s = rnd(2, 5); return { q: 'The transform of <span class="m">t · u(t)</span> is F(s). Evaluate F(s) at <span class="m">s = ' + s + '</span>.', a: 1 / (s * s), tol: 0.02, hint: 'F(s) = 1/s².', why: 'F(s) = 1/s² = 1/' + s * s + ' = ' + fmt(1 / (s * s), 4) + '.' }; } },
      { t: 'num', tier: 3, boss: true, gen() { const R = pick([0.1, 0.2, 0.5]), C = pick([50, 100, 200]); return { q: 'A source charges a <span class="m">' + C + ' µF</span> capacitor through <span class="m">' + R + ' Ω</span> of wire. The circuit settles in about <b>5τ</b>, where τ = RC. How long is that?', given: ['R = ' + R + ' Ω', 'C = ' + C + ' µF'], unit: 'µs', a: 5 * R * C, tol: 0.02, hint: 'τ = R·C. Ω × µF gives µs.', why: 'τ = RC = ' + fmt(R * C, 2) + ' µs, so 5τ = ' + fmt(5 * R * C, 2) + ' µs. The huge, brief current is modeled as an impulse.' }; } },
    ] },

  /* ---------------------------------------------------------------- 9 */
  { n: 9, diff: 4, topic: 'Laplace Toolkit and Inverse by Partial Fractions', theme: { parts: ['L', 'C'], phase: 90 },
    blurb: 'Transform rules, then go back to the time domain with partial fraction expansion.',
    intro: 'Two toolkits. A short list of <b>rules</b> turns one known pair into many. To go back from F(s) to f(t), split a big fraction into small ones you recognize: <b>partial fraction expansion</b>.',
    chals: [
      { t: 'match', tier: 1, q: 'Match each time-domain operation to its s-domain form.', pairs: [['Differentiation  df/dt', 'sF(s) − f(0⁻)'], ['Integration', 'F(s)/s'], ['Time delay  f(t−a)u(t−a)', 'e<sup>−as</sup>F(s)'], ['Frequency translation  e<sup>−at</sup>f(t)', 'F(s + a)']], why: 'Derivative becomes multiply by s (with the initial value), integral becomes divide by s, a delay becomes e<sup>−as</sup>, and a decay factor shifts s.' },
      { t: 'sort', tier: 1, q: 'Which partial fraction case is each denominator?', buckets: ['Simple real poles', 'Complex poles', 'Repeated poles', 'Improper: divide first'], items: [['(s + 1)(s + 2)', 0], ['s² + 6s + 10', 1], ['(s + 2)²', 2], ['Numerator degree is bigger than or equal to denominator degree', 3]], why: 'Simple poles: A/(s+p). Complex: (Bs+C)/(quadratic). Repeated: adds a B/(s+a)² term. Improper: do long division first.' },
      { t: 'num', tier: 2, gen() { const p1 = pick([1, 2]), p2 = pick([3, 4]), N = pick([6, 12]); return { q: 'Split <span class="m">F(s) = ' + N + ' / [(s + ' + p1 + ')(s + ' + p2 + ')]</span> into <span class="m">A/(s + ' + p1 + ') + B/(s + ' + p2 + ')</span>. Find A.', a: N / (p2 - p1), tol: 0.01, hint: 'Cover-up method: multiply by (s + ' + p1 + ') then plug in s = −' + p1 + '.', why: 'Cover-up: A = ' + N + '/(' + p2 + ' − ' + p1 + ') = ' + fmt(N / (p2 - p1), 3) + '.' }; } },
      { t: 'choice', tier: 2, q: 'A <b>repeated</b> pole at s = −a adds which time-domain piece?', opts: ['A t·e<sup>−at</sup> term', 'A plain sine wave', 'An impulse', 'Nothing new'], a: 0, hint: 'The table pair for 1/(s+a)².', why: 'A repeated pole (s+a)² gives a t·e<sup>−at</sup> term, besides the usual e<sup>−at</sup>.' },
      { t: 'order', tier: 2, q: 'Put the steps of an inverse Laplace transform in order.', items: ['Check the fraction is proper (divide first if not)', 'Factor the denominator', 'Write the expansion with unknown coefficients', 'Find the coefficients (cover-up or matching terms)', 'Look each simple piece up in the table'], hint: 'You cannot expand until the denominator is factored.', why: 'Always check afterwards: plug the coefficients back in and confirm the pieces recombine into F(s).' },
      { t: 'num', tier: 3, boss: true, gen() { const K = pick([2, 4, 6]), z = pick([1, 2, 3]), p = pick([2, 4]); return { q: 'Let <span class="m">F(s) = ' + K + '(s + ' + z + ') / [ s (s + ' + p + ') ]</span>. As t → ∞ the e<sup>−' + p + 't</sup> piece dies out. What constant does f(t) settle to?', a: K * z / p, tol: 0.01, hint: 'The constant is the coefficient A of 1/s. Cover up s and plug in s = 0.', why: 'A = ' + K + '(0 + ' + z + ')/(0 + ' + p + ') = ' + fmt(K * z / p, 3) + '. The f(t) piece with e<sup>−' + p + 't</sup> decays to 0.' }; } },
    ] },

  /* ---------------------------------------------------------------- 10 */
  { n: 10, diff: 4, topic: 'Circuits in the s-Domain', theme: { parts: ['L', 'C', 'R'], phase: -90 },
    blurb: 'Replace each part with its s-domain version, add initial-condition sources, then solve.',
    intro: 'Turn every part into an s-domain impedance (<span class="m">R, sL, 1/sC</span>), add a small extra source for any starting capacitor voltage or inductor current, then solve with ordinary tools. The result is the <b>total response</b> in one pass.',
    chals: [
      { t: 'match', tier: 1, q: 'Match each part to its s-domain impedance.', pairs: [['Resistor', 'R'], ['Inductor', 'sL'], ['Capacitor', '1/(sC)']], why: 'Resistor stays R. Inductor becomes sL. Capacitor becomes 1/(sC).' },
      { t: 'match', tier: 1, q: 'Match each kind of response to its meaning.', pairs: [['Zero-input', 'Natural response from stored energy, source off'], ['Zero-state', 'Forced response from the source, nothing stored'], ['Total', 'Zero-input plus zero-state'], ['Impulse response', 'Zero-state response to an impulse']], why: 'Total = zero-input + zero-state. The zero-state response is the same as convolution.' },
      { t: 'choice', tier: 2, q: 'An inductor starts with current I<sub>0</sub>. In the series s-domain model, what extra source appears?', opts: ['A voltage source L·I<sub>0</sub> in series', 'A voltage source I<sub>0</sub>/s in series', 'A current source C·I<sub>0</sub> in parallel', 'No extra source'], a: 0, hint: 'V = L[sI − I<sub>0</sub>] = sL·I − L·I<sub>0</sub>.', why: 'Series form: a voltage source L·I<sub>0</sub>. The parallel form is a current source I<sub>0</sub>/s. Both give the same answer.' },
      { t: 'choice', tier: 2, q: 'A capacitor starts at voltage V<sub>0</sub>. In the series s-domain model, what extra source appears?', opts: ['A voltage source V<sub>0</sub>/s in series', 'A voltage source L·V<sub>0</sub> in series', 'A current source V<sub>0</sub>/s in parallel', 'No extra source'], a: 0, hint: 'I = C[sV − V<sub>0</sub>] solved for V.', why: 'Series form: V<sub>0</sub>/s. Parallel form: a current source C·V<sub>0</sub>.' },
      { t: 'order', tier: 2, q: 'Put the s-domain analysis recipe in order.', items: ['Replace each source with its Laplace transform', 'Replace each part with its s-domain impedance', 'Add a source for each non-zero starting condition', 'Solve with Ohm’s law, KVL and KCL', 'Inverse transform to get the time response'], hint: 'Transform in, solve, transform out.', why: 'Five steps: transform sources, transform parts, add initial-condition sources, solve, then invert.' },
      { t: 'num', tier: 3, boss: true, gen() { const V0 = pick([6, 12, 24]), R = pick([1, 2, 4]), C = pick([0.5, 1, 2]), tau = R * C, t = pick([1, 2, 3]); return { q: 'A capacitor charged to <span class="m">' + V0 + ' V</span> discharges through <span class="m">' + R + ' kΩ</span>. <span class="m">C = ' + C + ' mF</span>. The voltage is v(t) = V<sub>0</sub> e<sup>−t/RC</sup>. What is v at <span class="m">t = ' + t + ' s</span>?', given: ['V<sub>0</sub> = ' + V0 + ' V', 'R = ' + R + ' kΩ', 'C = ' + C + ' mF'], unit: 'V', a: V0 * Math.exp(-t / tau), tol: 0.03, hint: 'kΩ × mF = seconds. Find τ = RC, then use the exponential.', why: 'τ = RC = ' + fmt(tau, 2) + ' s. v(' + t + ') = ' + V0 + ' e<sup>−' + t + '/' + fmt(tau, 2) + '</sup> = ' + fmt(V0 * Math.exp(-t / tau), 3) + ' V.' }; } },
    ] },

  /* ---------------------------------------------------------------- 11 */
  { n: 11, diff: 4, topic: 'Signals and Systems', theme: { parts: ['R', 'L'], phase: 20 },
    blurb: 'Treat a circuit as a box: linearity, time invariance and the impulse response.',
    intro: 'A circuit is a <b>system</b>: input signal in, output signal out. If it is <b>linear</b> and <b>time invariant</b>, its impulse response tells you everything about it.',
    chals: [
      { t: 'sort', tier: 1, q: 'Is each system linear?', buckets: ['Linear', 'Nonlinear'], items: [['y = x/2', 0], ['y = x²', 1], ['y = x − 2 (a constant offset)', 1], ['y = 3x', 0], ['y = |x|', 1]], why: 'Linear means superposition works: S{ax₁ + bx₂} = ay₁ + by₂. Squaring, absolute value and a constant offset all break it.' },
      { t: 'choice', tier: 1, q: 'A system is linear when S{a·x₁ + b·x₂} equals…', opts: ['a·y₁ + b·y₂', 'a·b·y₁·y₂', 'y₁ + y₂ + a + b', 'y₁ / y₂'], a: 0, hint: 'Scaling plus additivity.', why: 'The linearity test: plug in a·x₁ + b·x₂ and compare with a·y₁ + b·y₂. If they ever differ, the system is nonlinear.' },
      { t: 'sort', tier: 2, q: 'Is each system time invariant?', buckets: ['Time invariant', 'Not time invariant'], items: [['y(t) = t · x(t)', 1], ['y(t) = 2 + x²(t − 1)', 0], ['y(t) = 3 · x(t)', 0], ['y(t) = x(t − 2)', 0]], why: 'Time invariant means a delayed input gives the same output, delayed. For y = t·x(t), a delay also changes the amplitude, so it fails.' },
      { t: 'choice', tier: 2, q: 'What is the <b>impulse response</b> h(t)?', opts: ['The output when the input is δ(t) and all initial conditions are 0', 'The output when the input is a step', 'The input that makes the output zero', 'The steady-state output at 60 Hz'], a: 0, hint: 'h(t) = T{δ(t)}.', why: 'h(t) = T{δ(t)} with zero initial conditions. For an LTI system that one function describes the whole circuit.' },
      { t: 'num', tier: 2, gen() { const t = pick([1, 2, 3]); const h = (2 / 3) * (Math.exp(-t / 2) - Math.exp(-2 * t)); return { q: 'A series RLC circuit has impulse response <span class="m">h(t) = ⅔ (e<sup>−t/2</sup> − e<sup>−2t</sup>) u(t)</span>. Find h at <span class="m">t = ' + t + ' s</span>.', unit: '', a: h, tol: 0.03, hint: 'Plug t into both exponentials.', why: 'h(' + t + ') = ⅔(e<sup>−' + t / 2 + '</sup> − e<sup>−' + 2 * t + '</sup>) = ' + fmt(h, 4) + '.' }; } },
      { t: 'choice', tier: 3, boss: true, q: 'Which one of these systems is both <b>linear and time invariant</b>?', opts: ['y(t) = x(t)/2', 'y(t) = t · x(t)', 'y(t) = x(t) − 2', 'y(t) = 2 + x²(t − 1)'], a: 0, hint: 'Test linearity first, then time invariance.', why: 'y = x/2 scales its input (linear) and does not care when the input arrives (time invariant). The others fail one test: t·x is not time invariant, and the last two are not linear.' },
    ] },

  /* ---------------------------------------------------------------- 12 */
  { n: 12, diff: 5, topic: 'Convolution', theme: { parts: ['R', 'C', 'L'], phase: -30 },
    blurb: 'The convolution integral, the graphical method, and the shortcut Y(s) = X(s)H(s).',
    intro: 'Analyze the circuit once to find <b>h(t)</b>. After that the output for any input is the convolution integral. The Laplace shortcut turns that integral into plain multiplication: <span class="m">Y(s) = X(s) H(s)</span>.',
    chals: [
      { t: 'choice', tier: 1, q: 'When can you use the convolution integral to find the output?', opts: ['For a linear, time invariant system with no initial energy', 'For any system', 'Only for DC circuits', 'Only when the input is a step'], a: 0, hint: 'The derivation uses both properties.', why: 'The derivation delays (time invariance) and scales (linearity) impulses and adds them up. It assumes no initial energy.' },
      { t: 'order', tier: 1, q: 'Put the steps of the graphical convolution method in order.', items: ['Graph x(τ) versus τ', 'Graph h(t − τ): flip h, then slide it right by t', 'Multiply the two graphs point by point', 'The area under the product is y(t)', 'Repeat for each range of t where the overlap changes'], hint: 'Flip, then slide.', why: 'Each time an edge of one function crosses an edge of the other, you start a new case.' },
      { t: 'choice', tier: 2, q: 'What is the convolution theorem?', opts: ['y(t) = x(t) ∗ h(t) corresponds to Y(s) = X(s)H(s)', 'y(t) = x(t) · h(t) corresponds to Y(s) = X(s) + H(s)', 'y(t) = x(t) + h(t) corresponds to Y(s) = X(s)/H(s)', 'Convolution has no s-domain form'], a: 0, hint: 'Integral in time becomes a product in s.', why: 'With no initial energy, convolution in time is multiplication in the s-domain. For plain exponentials and steps this is usually the quicker route.' },
      { t: 'num', tier: 2, gen() { if (Math.random() < 0.5) { const t = pick([1, 2, 3]); return { q: 'An LTI system has <span class="m">h(t) = e<sup>−t</sup> u(t)</span> and input <span class="m">x(t) = u(t)</span>. The output is y(t) = 1 − e<sup>−t</sup>. Evaluate y at <span class="m">t = ' + t + ' s</span>.', a: 1 - Math.exp(-t), tol: 0.02, hint: 'Plug t into 1 − e<sup>−t</sup>.', why: 'y(' + t + ') = 1 − e<sup>−' + t + '</sup> = ' + fmt(1 - Math.exp(-t), 4) + '.' }; } const b = pick([2, 3]), t = pick([1, 2]); const y = (Math.exp(-t) - Math.exp(-b * t)) / (b - 1); return { q: 'Convolve <span class="m">x(t) = e<sup>−t</sup> u(t)</span> with <span class="m">h(t) = e<sup>−' + b + 't</sup> u(t)</span>. By the theorem, X(s)H(s) = 1/((s+1)(s+' + b + ')). Evaluate y at <span class="m">t = ' + t + ' s</span>.', a: y, tol: 0.03, hint: 'Partial fractions give y(t) = (e<sup>−t</sup> − e<sup>−' + b + 't</sup>) / ' + (b - 1) + '.', why: 'y(t) = (e<sup>−t</sup> − e<sup>−' + b + 't</sup>)/' + (b - 1) + ', so y(' + t + ') = ' + fmt(y, 4) + '.' }; } },
      { t: 'choice', tier: 3, q: 'Let <span class="m">x(t) = e<sup>t</sup> [u(t − 1) − u(t − 3)]</span> (it exists from t = 1 to 3) and let h(t) be a pulse of width 1 starting at 0. Over which range of t is the output <b>not</b> zero?', opts: ['1 ≤ t < 4', '0 ≤ t < 1', '1 ≤ t < 3', 't ≥ 4'], a: 0, hint: 'The sliding pulse starts to overlap at t = 1 and finishes leaving at t = 4.', why: 'The overlap changes at t = 1, 2, 3 and 4. Before 1 and after 4 the two do not overlap, so y = 0.' },
      { t: 'num', tier: 3, boss: true, gen() { const t = pick([2, 2.25, 2.5, 2.75]); return { q: 'Same setup: x(t) = e<sup>t</sup> from t = 1 to 3, and h(t) is a pulse of width 1. For <span class="m">2 ≤ t < 3</span> the pulse is fully inside, so <span class="m">y(t) = ∫<sub>t−1</sub><sup>t</sup> e<sup>τ</sup> dτ</span>. Find y at <span class="m">t = ' + t + '</span>.', a: Math.exp(t) - Math.exp(t - 1), tol: 0.02, hint: 'The antiderivative of e<sup>τ</sup> is e<sup>τ</sup>.', why: 'y(t) = e<sup>t</sup> − e<sup>t−1</sup>. At t = ' + t + ' that is ' + fmt(Math.exp(t) - Math.exp(t - 1), 3) + '. It matches the neighboring ranges at the boundaries.' }; } },
    ] },
];

/* ============ Composition: 16 levels, 1-2 per lecture, with the water-pipes analogy layer ============ */
const O = n => OLD[n - 1];
const C = (n, ...ix) => ix.map(i => O(n).chals[i]);
const lv = (n, lec, base, over, ana, chals) => Object.assign({}, base, over, { n, lec, chals, ana });

const NEW = {
  genChoice: { t: 'choice', tier: 2, q: 'Why are a generator’s three stator windings placed 120° apart?', opts: ['So the induced voltages are three equal sinusoids, 120° apart', 'To cancel the magnetic field completely', 'To make the output DC', 'So the rotor needs no power'], a: 0, hint: 'The flux through a winding goes as B·A·cos θ with θ = ωt.', why: 'The spinning field sweeps each winding at a different moment. Three windings 120° apart give three sinusoids, 120° apart.' },
  bossReal: { t: 'num', tier: 3, boss: true, gen() { const Vm = pick([100, 120, 170, 200]); return { q: 'A balanced abc set has <span class="m">V<sub>a</sub> = ' + Vm + '∠0°</span>. Find the real part of <span class="m">V<sub>b</sub> = ' + Vm + '∠−120°</span> (with V<sub>c</sub> it cancels V<sub>a</sub>).', a: -Vm / 2, abs: 0.01, tol: 0.001, hint: 'Real part = V<sub>m</sub> cos(−120°).', why: 'Re(V<sub>b</sub>) = ' + Vm + ' cos 120° = ' + (-Vm / 2) + '. V<sub>c</sub> also gives ' + (-Vm / 2) + ', and V<sub>a</sub> gives ' + Vm + ', so the sum is 0. Balanced sets add to zero.' }; } },
  combos: { t: 'match', tier: 1, q: 'Match each source and load connection to where you see it.', pairs: [['Y source, Y load', 'Most 3-phase equipment (about 75% has Y windings)'], ['Y source, Δ load', 'Very high-power motors (over about 50 HP)'], ['Δ source, Y load', 'Transformer connections such as Δ–Y step-up']], extra: ['Home wall outlets'], why: 'Y-Y is the most common. Big motors often use Δ loads. A Δ–Y transformer connection steps voltage up for transmission.' },
  split: { t: 'choice', tier: 2, q: 'A neighborhood transformer feeds a home with 120/240 V split-phase. How do the two hot wires relate?', opts: ['Two 120 V halves, 180° apart, sharing a neutral. Across both is 240 V', 'Two 120 V halves, 120° apart, with no neutral', 'Both are 240 V and in phase', 'One hot and one ground, 120 V'], a: 0, hint: '120 V circuits use one hot and the neutral. 240 V circuits use both hots.', why: 'Split-phase: hots at ∠0° and ∠180° share a neutral. One hot to neutral is 120 V. Hot to hot is 240 V.' },
  split2: { t: 'num', tier: 1, gen() { const V = pick([110, 120, 125]); return { q: 'In split-phase service each hot is <span class="m">' + V + ' V</span> from neutral, and the two hots are 180° apart. What is the voltage between the two hots?', unit: 'V', a: 2 * V, tol: 0.01, hint: 'Opposite angles add.', why: 'V∠0° minus V∠180° = 2V = ' + 2 * V + ' V.' }; } },
  deltaI: { t: 'num', tier: 2, gen() { const I = pick([25, 30, 60, 90]); return { q: 'A balanced Δ load draws a line current of <span class="m">' + I + ' A</span>. What is the current in each Δ leg (phase current)?', unit: 'A', a: I / R3, tol: 0.01, hint: 'In a Δ, the phase current is the line current ÷ √3.', why: '|I<sub>phase</sub>| = ' + I + '/√3 = ' + fmt(I / R3, 2) + ' A.' }; } },
  total3: { t: 'choice', tier: 1, q: 'For a balanced load, how does total real power relate to the power in one phase?', opts: ['P<sub>T</sub> = 3 P<sub>φ</sub>', 'P<sub>T</sub> = P<sub>φ</sub>', 'P<sub>T</sub> = √3 P<sub>φ</sub>', 'P<sub>T</sub> = P<sub>φ</sub> / 3'], a: 0, hint: 'Three identical copies.', why: 'Three-phase power is three copies of single-phase power. In terms of line values: P<sub>T</sub> = √3 · V<sub>line</sub> · I<sub>line</sub> · cos θ.' },
  perPhase: { t: 'num', tier: 2, gen() { const V = pick([208, 400, 480]), I = pick([10, 20, 30]), pf = pick([0.8, 0.9]); return { q: 'A balanced <b>Y</b> load: line voltage <span class="m">' + V + ' V</span>, line current <span class="m">' + I + ' A</span>, pf <span class="m">' + pf + '</span>. Find the real power in <b>one phase</b>.', unit: 'W', a: V / R3 * I * pf, tol: 0.02, hint: 'P<sub>φ</sub> = (V<sub>line</sub>/√3) · I<sub>line</sub> · pf for a Y load.', why: 'P<sub>φ</sub> = (' + V + '/√3)(' + I + ')(' + pf + ') = ' + fmt(V / R3 * I * pf, 1) + ' W.' }; } },
  outlet: { t: 'match', tier: 1, q: 'Match each part of a wall outlet to its job.', pairs: [['Short slot', 'Hot (carries the live 120 V)'], ['Longer slot', 'Neutral (the return path)'], ['Round hole', 'Ground (safety path to earth)']], extra: ['Surge lock'], why: 'If hot touches a metal case, the fault current returns through the ground wire and not through you.' },
  bodyI: { t: 'num', tier: 3, boss: true, gen() { const V = pick([120, 240]), R = pick([500, 1000, 1500]); return { q: 'Wet skin makes the body’s hand-to-hand resistance about <span class="m">' + R + ' Ω</span>. You touch <span class="m">' + V + ' V</span>. How much current flows?', unit: 'mA', a: V / R * 1000, tol: 0.02, hint: 'I = V / R, then convert A to mA.', why: 'I = ' + V + '/' + R + ' = ' + fmt(V / R * 1000, 0) + ' mA. Compare with the table: 75 to 400 mA can cause ventricular fibrillation. Current, not voltage, is what hurts.' }; } },
  diff: { t: 'choice', tier: 1, q: 'In the s-domain, the derivative df/dt becomes…', opts: ['sF(s) − f(0⁻), so the initial value is built in', 'sF(s) with no extra term', 'F(s)/s', 'e<sup>−s</sup>F(s)'], a: 0, hint: 'Derivative becomes multiply by s.', why: 'Differentiation: df/dt ↔ sF(s) − f(0⁻). Integration is the opposite: divide by s.' },
  scale: { t: 'choice', tier: 2, q: 'Speeding up time, f(at), has which s-domain form?', opts: ['(1/a) F(s/a)', 'a F(as)', 'F(s − a)', 'e<sup>−as</sup> F(s)'], a: 0, hint: 'Scale change speeds up or slows down time.', why: 'Scale change: f(at) ↔ (1/a)F(s/a). Frequency translation e<sup>−at</sup>f(t) ↔ F(s+a) is the one that shifts s.' },
  transl: { t: 'num', tier: 2, gen() { const a = rnd(1, 3), w = rnd(1, 3), s = rnd(0, 2); const v = (s + a) / ((s + a) ** 2 + w * w); return { q: 'Start with <span class="m">cos(ωt) ↔ s/(s² + ω²)</span>. Frequency translation gives <span class="m">e<sup>−at</sup>cos(ωt) ↔ (s + a)/((s + a)² + ω²)</span>. Evaluate it for <span class="m">a = ' + a + ', ω = ' + w + ', s = ' + s + '</span>.', a: v, tol: 0.02, hint: 'Plug in s + a = ' + (s + a) + '.', why: '(' + (s + a) + ')/(' + (s + a) + '² + ' + w * w + ') = ' + fmt(v, 4) + '.' }; } },
  tcos: { t: 'num', tier: 3, boss: true, gen() { const s = rnd(2, 4), w = rnd(1, 2); const v = (s * s - w * w) / ((s * s + w * w) ** 2); return { q: 'Multiplying by t is s-differentiation: <span class="m">t·cos(ωt) ↔ (s² − ω²)/(s² + ω²)²</span>. Evaluate it at <span class="m">s = ' + s + '</span> with <span class="m">ω = ' + w + '</span>.', a: v, tol: 0.02, hint: 'Compute the top and bottom separately.', why: 'Top: ' + s * s + ' − ' + w * w + ' = ' + (s * s - w * w) + '. Bottom: (' + (s * s + w * w) + ')² = ' + (s * s + w * w) ** 2 + '. Ratio: ' + fmt(v, 5) + '.' }; } },
  improper: { t: 'choice', tier: 2, q: '<span class="m">F(s) = 4s − 1 + (s + 3)/(s² + 3s + 2)</span> is improper before dividing. What does the polynomial part <span class="m">4s − 1</span> become in the time domain?', opts: ['4δ′(t) − δ(t), which are impulses', '4u(t) − δ(t)', '4t − 1', 'It is thrown away'], a: 0, hint: 's ↔ δ′(t), and a constant ↔ δ(t).', why: 'Improper fractions give impulses (δ and δ′). The proper leftover splits as 2/(s+1) − 1/(s+2).' },
  l10_match: { t: 'match', tier: 1, q: 'Match each situation to the tool used for it.', pairs: [['Two-loop circuit, zero start', 'Cramer’s rule on the KVL equations'], ['Shrink the circuit first', 'Thevenin equivalent in the s-domain'], ['Coupled inductors', 'T-equivalent circuit'], ['Parallel RLC with a switch', 'Rewrite the source as I₀u(t)']], why: 'Once a circuit is in the s-domain it is just algebra. Pick the easiest solver.' },
  l10_dot: { t: 'choice', tier: 2, q: 'The T-equivalent circuit assumes the dots are on the same side of each inductor. If they are not, what do you do?', opts: ['Replace each M with −M', 'Ignore the mutual inductance', 'Double M', 'Swap the two inductors'], a: 0, hint: 'The dot convention flips the sign of M.', why: 'With dots on opposite sides, replace each M with −M in the T-equivalent.' },
  l10_cramer: { t: 'num', tier: 2, gen() { let a, b, c, d, x, y; do { a = rnd(1, 5); b = rnd(1, 4); c = rnd(1, 4); d = rnd(1, 5); x = rnd(1, 6); y = rnd(1, 6); } while (a * d - b * c === 0); const e = a * x + b * y, f = c * x + d * y; return { q: 'Solve the loop equations with Cramer’s rule and report <span class="m">y</span>.<br><span class="m">' + a + 'x + ' + b + 'y = ' + e + '</span><br><span class="m">' + c + 'x + ' + d + 'y = ' + f + '</span>', a: y, tol: 0.001, abs: 0.001, hint: 'y = (a·f − c·e) / (a·d − b·c).', why: 'det = ' + a + '·' + d + ' − ' + b + '·' + c + ' = ' + (a * d - b * c) + '. y = (' + a + '·' + f + ' − ' + c + '·' + e + ')/det = ' + y + '.' }; } },
  l10_init: { t: 'num', tier: 2, gen() { const V = pick([60, 48, 24]), R1 = pick([9, 6, 4]), R2 = pick([3, 2, 4]); return { q: 'Before a make-before-break switch moves at t = 0, the circuit sits at steady state: <span class="m">' + V + ' V</span> across <span class="m">' + R1 + ' Ω + ' + R2 + ' Ω</span> in series, and the inductors act like wires. Find the starting current <span class="m">i<sub>1</sub>(0)</span>.', unit: 'A', a: V / (R1 + R2), tol: 0.01, hint: 'Steady state: inductors are shorts. Use Ohm’s law on the total resistance.', why: 'i<sub>1</sub>(0) = ' + V + '/(' + R1 + ' + ' + R2 + ') = ' + fmt(V / (R1 + R2), 3) + ' A. (The second loop starts at 0.)' }; } },
  l10_check: { t: 'choice', tier: 2, q: 'After inverting, what quick check should you always run on the answer?', opts: ['Check that the value at t = 0⁺ matches the circuit’s starting conditions', 'Check that every term is positive', 'Check that the answer has no exponentials', 'Check that the units are volts'], a: 0, hint: 'The answer must be consistent with how the circuit started.', why: 'In the worked example, i₂(0⁺) = 7 − 8.4 + 1.4 = 0, which matches a circuit that starts with zero in loop 2.' },
  l10_boss: { t: 'num', tier: 3, boss: true, gen() { const t = pick([0.05, 0.1, 0.2, 0.5]); const v = 7 - 8.4 * Math.exp(-2 * t) + 1.4 * Math.exp(-12 * t); return { q: 'Cramer’s rule gave <span class="m">i<sub>2</sub>(t) = 7 − 8.4e<sup>−2t</sup> + 1.4e<sup>−12t</sup></span> A for t ≥ 0. Find i<sub>2</sub> at <span class="m">t = ' + t + ' s</span>.', unit: 'A', a: v, tol: 0.03, abs: 0.02, hint: 'Compute each exponential, then combine.', why: 'i₂(' + t + ') = 7 − 8.4e^(−' + 2 * t + ') + 1.4e^(−' + 12 * t + ') = ' + fmt(v, 3) + ' A. As t grows it settles toward 7 A.' }; } },
};

const T0 = i => O(i); // base fields (topic, theme, blurb, intro, diff)
const GRID_LEVELS = [
  lv(1, 1, O(1), {}, { title: 'Mill Water vs Sloshing Water', mission: 'Pressure times flow is power. Which water spins the mill and which only sloshes?' }, O(1).chals),
  lv(2, 2, O(2), {}, { title: 'Pushing in Step', mission: 'How much of the push really spins the wheel? Find the share.' }, O(2).chals),
  lv(3, 2, O(3), {}, { title: 'Sizing the Pipe', mission: 'Mill water plus sloshing water decide how big your pipe must be.' }, O(3).chals),
  lv(4, 3, O(4), {}, { title: 'The Balloon Tank Repair', mission: 'Stop the sloshing from clogging the main pipe. Fit a tank beside the load.' }, O(4).chals),
  lv(5, 3, O(5), { topic: 'Three-Phase Basics', blurb: 'Balanced sets, abc and acb order, why the grid uses three phases, and how a generator makes them.', intro: 'Three-phase power is three AC waves offset by 120°. A balanced set adds to zero at every instant, which is why it needs so few wires.', diff: 2, theme: { parts: ['R', 'R', 'R'], phase: 120 } }, { title: 'Three Pistons', mission: 'Three pistons, each a third of a turn behind the last. Keep them balanced.' }, [...C(5, 0, 1, 2, 3), NEW.genChoice, NEW.bossReal]),
  lv(6, 4, O(5), { topic: 'The Real Grid and the Balanced Y-Y Circuit', blurb: 'From generator to outlet, source and load connections, split-phase, and why a balanced neutral carries nothing.', intro: 'Sources and loads come in two shapes: <b>Y</b> (three branches meeting at a center) and <b>Δ</b> (a triangle). If all three phases are identical, the neutral wire carries zero current, and you can solve one phase.', diff: 3, theme: { parts: ['R', 'L', 'R'], phase: 120 } }, { title: 'The Pipe Network', mission: 'Follow the water from the reservoir to the kitchen faucet.' }, [NEW.split2, NEW.combos, C(5, 4)[0], NEW.split, C(6, 1)[0], C(5, 5)[0]]),
  lv(7, 5, O(6), { topic: 'Y-Y and Y-Δ Analysis', diff: 3 }, { title: 'Hubs and Triangles', mission: 'Swap a triangle of pipes for a hub, then solve just one pipe.' }, [C(6, 0)[0], C(6, 2)[0], C(6, 3)[0], C(6, 4)[0], NEW.deltaI, C(6, 5)[0]]),
  lv(8, 6, O(7), { topic: 'Three-Phase Power', blurb: 'Total power from line values, and why it never wiggles.', intro: 'Total real power is <span class="m">P = √3 · V<sub>line</sub> · I<sub>line</sub> · cos θ</span>. The three phases fill in each other’s dips, so the total never wiggles.', diff: 3 }, { title: 'Smooth Flow', mission: 'Three pistons fill in each other’s dips. Size the total flow.' }, [C(7, 0)[0], NEW.total3, NEW.perPhase, C(7, 2)[0], C(7, 5)[0]]),
  lv(9, 6, O(7), { topic: 'Plugs, Grounding and Shock Safety', blurb: 'Outlet parts, GFCIs vs breakers, and what current does to the body.', intro: 'Safety half of the day: <b>current</b>, not voltage, hurts you. A few milliamps is already enough to lose control of your muscles.', diff: 3 }, { title: 'Safe Taps', mission: 'A little flow tingles. More clamps your hand. Keep the drain pipes working.' }, [NEW.outlet, C(7, 1)[0], C(7, 3)[0], C(7, 4)[0], NEW.bodyI]),
  lv(10, 7, O(8), {}, { title: 'The Faucet and the Hammer Tap', mission: 'A faucet turned on, and a hammer tap. Learn the two basic moves.' }, O(8).chals),
  lv(11, 8, O(9), { topic: 'Laplace Operations', blurb: 'Rules that turn one transform pair into many.', intro: 'A short list of <b>rules</b> (shift, scale, derivative) turns one known transform pair into many more.', diff: 3 }, { title: 'Fittings for s Land', mission: 'Rules that turn one known fitting into many.' }, [C(9, 0)[0], NEW.diff, NEW.scale, NEW.transl, NEW.tcos]),
  lv(12, 8, O(9), { topic: 'Inverse Laplace by Partial Fractions', blurb: 'Split a messy F(s) into simple pieces and look them up.', intro: 'To go back from F(s) to f(t), split a big fraction into small ones you recognize: <b>partial fraction expansion</b>.', diff: 4 }, { title: 'Break the Bill into Coins', mission: 'Split a messy flow into simple pieces you can look up.' }, [C(9, 1)[0], C(9, 2)[0], C(9, 3)[0], NEW.improper, C(9, 4)[0], C(9, 5)[0]]),
  lv(13, 9, O(10), {}, { title: 'Redraw the Plumbing', mission: 'Redraw each part for s land and add the starting water.' }, O(10).chals),
  lv(14, 10, O(10), { topic: 'Laplace Circuit Examples', blurb: 'Cramer’s rule, Thevenin, mutual inductance, and the always-check habit.', intro: 'Once a circuit is in the s-domain it is just algebra. Pick the easiest solver (Cramer’s rule for loops, Thevenin to shrink the circuit) and finish with a partial-fraction inverse. Always check the answer at t = 0⁺.', diff: 4, theme: { parts: ['L', 'L', 'R'], phase: 60 } }, { title: 'Four Plumbing Jobs', mission: 'Solve whole networks, then check the first drop matches the start.' }, [NEW.l10_match, NEW.l10_dot, NEW.l10_cramer, NEW.l10_init, NEW.l10_check, NEW.l10_boss]),
  lv(15, 11, O(11), {}, { title: 'Black Box Plumbing', mission: 'Test the box: does it scale, and does it care when?' }, O(11).chals),
  lv(16, 12, O(12), {}, { title: 'Slide and Add the Splashes', mission: 'Add up delayed, scaled splashes to get the output.' }, O(12).chals),
];
GRID_LEVELS.forEach(l => { const a = ANA_L[l.lec]; if (a) { l.ana.key = a.key; l.ana.map = a.map; } });
